package com.hotelpms.frontdesk.workflow.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="workflow_transition_audit") public class WorkflowTransitionAudit { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="hotel_id",nullable=false) private UUID hotelId; @Column(name="workflow_id",nullable=false) private UUID workflowId; @Column(name="aggregate_id",nullable=false) private UUID aggregateId; @Column(name="from_state_key",nullable=false) private String fromStateKey; @Column(name="to_state_key",nullable=false) private String toStateKey; @Enumerated(EnumType.STRING) @Column(name="semantic_phase",nullable=false) private SemanticPhase semanticPhase; @Column(name="actor_id",nullable=false) private String actorId; @Column(name="created_at",nullable=false) private Instant createdAt; protected WorkflowTransitionAudit(){} public WorkflowTransitionAudit(UUID h,UUID w,UUID a,String f,String t,SemanticPhase p,String actor){hotelId=h;workflowId=w;aggregateId=a;fromStateKey=f;toStateKey=t;semanticPhase=p;actorId=actor;createdAt=Instant.now();} }
